import moment from 'moment'
import 'moment/locale/id'
import { useMemo } from 'react'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { formatMoney, getConvertedCurrency } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../../../../CommonContainer/OfflinePolicyContainer/components/PolicyInfoRender'
import { QuoteInstalmentListStyle } from './index.style'
moment.locale('id')

const QuoteInstalmentList = props => {
  const { instalments = [], policy } = props
  const tableData = useMemo(() => {
    const data = [
      {
        title: <span className='bold-black'>{LANG_STRINGS.instalmentDueDate}</span>,
        value: LANG_STRINGS.payableAmount
      },
      ...instalments.map(x => (
        {
          title: moment(x.due_date, 'YYYY/MM/DD').format('DD MMMM YYYY'),
          value: policy.currency_symbol !== 'Rp'
            ? formatMoney(getConvertedCurrency(x.payable_amount, policy.exchange_rate), 0, policy.currency_symbol, '.', ',')
            : formatMoney(x.payable_amount, ''),
          ...(x.serial_number === 1 ? { bgColor: AgentColorPallette.Gray90 } : {})
        }
      ))
    ]
    return data
  }, [instalments, policy.currency_symbol, policy.exchange_rate])
  return (
    <QuoteInstalmentListStyle>
      <div className='border-btm padding-btm'>
        <PolicyInfoRender
          data={tableData}
          name='instalments-info'
        />
      </div>
    </QuoteInstalmentListStyle>
  )
}

export default QuoteInstalmentList
