import moment from 'moment'
import { useMemo, useCallback } from 'react'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { getPolicyStatus } from '../../../../../helpers/data'
import { formatMoney, getConvertedCurrency, getFileNameFromUrl } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import { BENEFIT_TYPE_MAP } from '../../../../Private/Policy/constants'
import PolicyInfoRender from '../PolicyInfoRender'

function OfflinePolicyData ({ isManualOrder, policy = {}, isTransactionDetail }) {
  const getProviderNames = useCallback((providers = []) => {
    const providerNames = providers.map(provider => provider.name)
    return providerNames.join(', ')
  }, [])

  const policyData = useMemo(() => {
    let policyItems = []
    let providerObj = []
    const discountMap = []
    if (!isTransactionDetail) {
      providerObj = [{
        title: LANG_STRINGS.insuranceProvider,
        display: 'block',
        value: getProviderNames(policy.prov_maps)
      }]
      discountMap.push({
        title: LANG_STRINGS.discount,
        value: policy.discount ? `${policy.discount}%` : '-'
      })
    }
    if (policy.policy_status) {
      const policyStatus = getPolicyStatus(policy?.expired ? 'EXPIRED' : policy.policy_status)
      policyItems.push({
        title: LANG_STRINGS.policyStatus,
        value: policyStatus.text,
        color: policyStatus.color
      })
    }
    if (isManualOrder) {
      policyItems = [
        ...policyItems,
        {
          title: LANG_STRINGS.benefitType,
          value: BENEFIT_TYPE_MAP[policy.package_type]
        },
        ...providerObj
      ]
    } else {
      policyItems = [
        ...policyItems,
        {
          title: LANG_STRINGS.premiumCalculationNote,
          display: 'block',
          value: getFileNameFromUrl(policy?.premium_calculation_note) || '-'
        },
        ...providerObj,
        ...(policy.loss_ratio ? [{
          title: LANG_STRINGS.lossRatio,
          value: formatMoney(policy.loss_ratio, 0)
        }] : []),
        {
          title: LANG_STRINGS.totalGwpBasedOnOjk,
          display: 'block',
          value: formatMoney(getConvertedCurrency(policy.total_gwp_ojk_rate, policy?.exchange_rate), 2,
            policy.currency_symbol, policy.currency_symbol === 'Rp' ? ',' : '.',
            policy.currency_symbol === 'Rp' ? '.' : ',')
        }
      ]
    }
    return [
      ...policyItems,
      {
        title: LANG_STRINGS.policyStartDate,
        value: moment(policy?.coverage_period_start, 'YYYY-MM-DD').format('DD MMM YYYY')
      },
      {
        title: LANG_STRINGS.policyEndDate,
        value: policy?.coverage_period_end ? moment(policy?.coverage_period_end, 'YYYY-MM-DD').format('DD MMM YYYY') : '-'
      },
      {
        title: LANG_STRINGS.period,
        value: policy?.coverage_period ? `${policy?.coverage_period || policy?.period} tahun` : '-'
      },
      ...discountMap
    ]
  }, [isManualOrder, policy, isTransactionDetail, getProviderNames])

  return (
    <CollapsibleCard
      className='offline-collapsible-card-wrapper'
      title={LANG_STRINGS.policyData}
      isOpen
      key='offlineData'
    >
      <PolicyInfoRender
        data={policyData}
        name='policyOfflineData'
      />
    </CollapsibleCard>
  )
}

export default OfflinePolicyData
