import { useMemo } from 'react'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { getVehicleType } from '../../../../../helpers/data'
import { formatMoney, getConvertedCurrency } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../PolicyInfoRender'

function OfflineTransportationType ({ policyData = {} }) {
  const transportationData = useMemo(() => ([
    {
      title: LANG_STRINGS.transportationType,
      value: getVehicleType(policyData?.vehicle_type)
    },
    {
      title: LANG_STRINGS.vehicleUse,
      value: policyData?.usage
    },
    {
      title: LANG_STRINGS.productionYear,
      value: policyData?.year
    },
    {
      title: LANG_STRINGS.vehicleBrands,
      value: policyData?.brand ? (policyData?.brand_other ? policyData.brand : policyData?.brand_data?.name) : ''
    },
    {
      title: LANG_STRINGS.vehicleModel,
      display: 'block',
      value: policyData?.model ? (policyData?.model_other ? policyData?.model : policyData?.model_name) : ''
    },
    {
      title: LANG_STRINGS.price,
      value: policyData?.currency_label === 'IDR'
        ? formatMoney(policyData?.vehicle_sum_insured, 0)
        : `${policyData?.currency_symbol || 'Rp'} ${getConvertedCurrency(policyData?.vehicle_sum_insured, policyData?.exchange_rate)}`
    },
    {
      title: LANG_STRINGS.vehicleNumber,
      value: `${policyData?.region_code} ${policyData?.vehicle_plate_no}`
    }
  ]), [policyData])

  return (
    <CollapsibleCard
      className='offline-collapsible-card-wrapper'
      title={LANG_STRINGS.transactionType}
      isOpen
      key='offlineTransportationType'
    >
      <PolicyInfoRender
        data={transportationData}
        name='policyOfflineData'
      />
    </CollapsibleCard>
  )
}

export default OfflineTransportationType
