import get from 'lodash/get'
import moment from 'moment'
import 'moment/locale/id'
import { useMemo, useState } from 'react'
import { CustomText } from '../../../../../components'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { DOWN_ARROW_GOLD } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../../../../CommonContainer/OfflinePolicyContainer/components/PolicyInfoRender'
import InstalmentList from '../InstalmentList'
import QuoteInstalmentList from '../QuoteInstalmentList'
import { InstalmentsInfoStyle } from './index.style'
moment.locale('id')

const InstalmentsInfo = (props) => {
  const { instalmentsData, isQuote = false, policy } = props
  const [showDetails, setShowDetails] = useState(false)
  const instalments = get(instalmentsData, 'instalment_details')
  const instalmentPeriod = get(instalmentsData, 'instalment_period')
  const totalInstalments = get(instalmentsData, 'total_instalments')
  const tableData = useMemo(() => {
    const currentInstalment = policy?.upcoming_instalment
    let data = [
      {
        title: LANG_STRINGS.period,
        value: instalmentPeriod ? `${instalmentPeriod} Bulan` : '-'
      },
      {
        title: LANG_STRINGS.totalInstalments,
        value: totalInstalments ? `${totalInstalments} Kali` : '-'
      }
    ]
    if (!isQuote) {
      data = [
        ...data,
        {
          title: `${LANG_STRINGS.instalmentDueDate} ${LANG_STRINGS.instalmentSequenceNumber} ${currentInstalment?.serial_number}`,
          value: instalments ? moment(currentInstalment?.due_date, 'YYYY/MM/DD').format('DD MMMM YYYY') : '-'
        }
      ]
    }
    data = [
      ...data,
      {
        value: (
          <CustomText
            className='instalment-details-btn'
            onClick={() => setShowDetails(true)}
            color={AgentColorPallette.uiGold}
            weight={800}
            size='13px'
            padRight='3px'
          >
            {LANG_STRINGS.instalmentsDetail} &nbsp; <img src={DOWN_ARROW_GOLD} alt='show details' />
          </CustomText>
        ),
        color: AgentColorPallette.goldDarker
      }
    ]
    return data
  }, [instalments, instalmentPeriod, totalInstalments, isQuote, policy])

  if (!instalmentsData) {
    return null
  }
  return (
    <InstalmentsInfoStyle>
      <CollapsibleCard
        className='offline-collapsible-card-wrapper'
        title={LANG_STRINGS.payInInstalments}
        isOpen
        key='instalmentsData'
      >
        <PolicyInfoRender
          data={tableData}
          name='instalments-info'
        />
      </CollapsibleCard>
      <BottomActionSheet
        title={LANG_STRINGS.instalmentsDetail}
        show={showDetails}
        showHeader
        onCloseSheet={() => setShowDetails(false)}
      >
        {isQuote
          ? <QuoteInstalmentList instalments={instalments} policy={policy} />
          : <InstalmentList instalments={instalments} currentInstalment={policy?.upcoming_instalment || {}} policy={policy.policy_detail} />}
      </BottomActionSheet>
    </InstalmentsInfoStyle>
  )
}

export default InstalmentsInfo
