import { useCallback } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import Collapsible from '../../../../../components/Collapsible'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { AddonsCategoryStyle } from './index.style'

function AddonsWithCategory ({ addonsData, customAddonsData = [] }) {
  const renderAddonTitleCheck = useCallback(addon => (
    <Row align='center' justify='space-between' key={`addon-category-item$-${addon.add_on_code || addon.key}`}>
      <CustomText color={AgentColorPallette.fontDarkerGrey} size='10px'>
        {addon.add_on_name}
      </CustomText>
      <CustomText color={AgentColorPallette.green}>
        <i className='fa fa-check' />
      </CustomText>
    </Row>
  ), [])

  const renderSelectedAddonsList = useCallback(() => {
    const addonsMap = []
    let addonsLength = Object.keys(addonsData).length
    for (const categoryKey in addonsData) {
      const categoryItems = addonsData[categoryKey]
      addonsLength -= 1
      const item = (
        <Collapsible
          header={categoryKey}
          bodyPadding='2px 0'
          isOpen
          className='addons-collapsible-header'
          key={`addons-category-${categoryKey}`}
        >
          {
            (function () {
              const itemsMap = []
              for (const addonKey in categoryItems) {
                const addon = categoryItems[addonKey]
                const categoryElement = renderAddonTitleCheck(addon)
                itemsMap.push(categoryElement)
              }
              return itemsMap
            })()
          }
        </Collapsible>
      )
      addonsMap.push(item)
      if (addonsLength !== 0) {
        addonsMap.push(<div className='separator-line' />)
      }
    }
    if (customAddonsData?.length) {
      const customAddonMaps = []
      for (let index = 0; index < customAddonsData.length; index++) {
        const addon = customAddonsData[index]
        customAddonMaps.push(renderAddonTitleCheck(addon))
      }
      const CustomAddonCollapsible = (
        <Collapsible
          header={LANG_STRINGS.otherProtection}
          bodyPadding='2px 0'
          isOpen
          className='addons-collapsible-header'
        >
          {customAddonMaps}
        </Collapsible>
      )
      if (addonsMap.length) {
        addonsMap.push(<div className='separator-line' />)
      }
      addonsMap.push(CustomAddonCollapsible)
    }
    return addonsMap
  }, [addonsData, customAddonsData, renderAddonTitleCheck])

  return (
    <AddonsCategoryStyle>
      {renderSelectedAddonsList()}
    </AddonsCategoryStyle>
  )
}

export default AddonsWithCategory
