import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { LANG_STRINGS } from '../../../../../lang'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import AddonsWithCategory from '../../../../Private/Policy/components/PolicyAddonsWithCatgory'
import { useMemo } from 'react'
import { AddOnsStyleWrapper } from '../../../../Private/Policy/pages/OfflinePolicyReviewForm/container/index.style'

function OfflinePolicyAddonsData ({ policyData }) {
  const isAddonsData = useMemo(() => {
    return !!(policyData.addons && Object.keys(policyData.addons)?.length) ||
    !!policyData?.custom_add_on?.length
  }, [policyData])
  return (
    <AddOnsStyleWrapper>
      <CollapsibleCard title={LANG_STRINGS.packageAddons} isOpen key='addonsData'>
        {
          isAddonsData ? (
            <AddonsWithCategory
              addonsData={policyData.addons}
              customAddonsData={policyData.custom_add_on}
            />
          )
            : (
              <CustomText color={AgentColorPallette.darkCharcoal}>
                {LANG_STRINGS.nothing}
              </CustomText>
            )
        }
      </CollapsibleCard>
    </AddOnsStyleWrapper>
  )
}

export default OfflinePolicyAddonsData
