import { useCallback, useEffect, useMemo, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { Row } from '../../../commonStyle/index.style'
import TitleEditHeading from '../../../components/TitleEditHeading'
import { OFFLINE_FORM_DATA } from '../../../constants/cookies'
import { setToLocalStorage } from '../../../helpers/localstorage'
import { LANG_STRINGS } from '../../../lang'
import OfflinePolicyAddonsData from './components/OfflineAddonsData'
import OfflinePolicyData from './components/OfflinePolicyData'
import OfflineTransportationType from './components/OfflineTransportationType'
import PolicyHolderInfo from './components/PolicyHolderInfo'
import PrintPolicyData from './components/PrintPolicyData'
import VehicleAttachmentData from './components/VehicleAttachmentData'
import VehicleData from './components/VehicleData'
import VehicleModificationData from './components/VehicleModificationData'
import VehiclePhotoData from './components/VehiclePhotoData'
import { InstantApprovalCard, InstantTermsStyle, OfflinePolicyDataStyle } from './index.style'
import CustomText from '../../../components/CustomText/index'
import CustomCheckbox from '../../../components/CustomCheckbox'
import { AgentColorPallette } from '../../../configs/colorPallete'
import BottomActionSheet from '../../../components/BottomActionSheet'
import InstalmentsInfo from '../../Private/Policy/components/InstalmentsInfo'
import { get, isEmpty } from 'lodash'

function OfflinePolicyContainer ({ pageConfig, policyData = {}, quoteData = {}, onInstantChecked = () => {}, isHideInstantChecked = false }) {
  const history = useHistory()
  const [showInstantTerms, setInstantTerms] = useState(false)
  const [checkedInstantApproval, setCheckedInstantApproval] = useState(pageConfig.isOfflineOrderDetail ? policyData.instant_approve : (policyData.prov_maps?.length === 1))
  const handleEdit = useCallback((step) => {
    if (pageConfig.quoteId) {
      setToLocalStorage(OFFLINE_FORM_DATA, policyData)
    }
    const quoteId = pageConfig.quoteId || 'normal'
    if (step === 1) {
      history.push(`/car-protection/${policyData?.protection_case}/${quoteId}/order/edit`)
    } else {
      history.push(`/car-protection/${policyData?.protection_case}/${quoteId}/offline/form/edit`)
    }
  }, [policyData, history, pageConfig.quoteId])
  const mapHardCopyData = useMemo(() => {
    return {
      hard_copy_required: policyData.hard_copy_required,
      insurance_details: {
        hard_copy_address: policyData.hard_copy_address,
        hard_copy_details: {
          recipient_name: policyData.hard_copy_recipient,
          hard_copy_recipient_mobile: policyData.hard_copy_recipient_mobile
        }
      }
    }
  }, [policyData])

  const handleCheckbox = useCallback(() => {
    setCheckedInstantApproval(checked => {
      onInstantChecked(!checked)
      return !checked
    })
  }, [onInstantChecked])

  useEffect(() => {
    onInstantChecked(policyData.prov_maps?.length === 1)
  }, [onInstantChecked, policyData.prov_maps])

  const handleShowTermsToggle = useCallback(() => {
    setInstantTerms(prevShow => !prevShow)
  }, [])

  const renderInstantApproval = () => {
    return (
      <InstantApprovalCard>
        <Row
          align='center'
          justify='space-between'
          className='pad-12'
        >
          <CustomText
            color={AgentColorPallette.fontDarkerGrey}
            size='14px'
            weight={800}
          >
            {LANG_STRINGS.partnerApproval}
          </CustomText>
          <CustomCheckbox
            onChange={handleCheckbox}
            name='instant_approval'
            disabled={pageConfig.isOfflineOrderDetail}
            isChecked={checkedInstantApproval}
            color={AgentColorPallette.black}
          />
        </Row>
        <CustomText
          color={AgentColorPallette.blackGrey}
          className='instant-terms-body'
        >
          {LANG_STRINGS.iAgreeWith}
          <span className='offline-terms' onClick={handleShowTermsToggle}>&nbsp;{LANG_STRINGS.termsConditions}</span>
        </CustomText>
      </InstantApprovalCard>
    )
  }

  return (
    <>
      <OfflinePolicyDataStyle>
        <TitleEditHeading
          title={LANG_STRINGS.dataChecking}
          onEditClick={() => handleEdit(1)}
          showEditBtn={pageConfig.showEditQuoteData}
        />
        <OfflinePolicyData
          isManualOrder={pageConfig.isManualOrder}
          policy={policyData}
        />
        <OfflinePolicyAddonsData
          policyData={policyData}
        />
      </OfflinePolicyDataStyle>
      <div className='separator' />
      <OfflinePolicyDataStyle padBtm='20%'>
        <TitleEditHeading
          title={LANG_STRINGS.insuredObject}
          onEditClick={() => handleEdit(2)}
          showEditBtn={pageConfig.showEditQuoteData}
        />
        {
          pageConfig.isManualOrder && (
            <>
              <OfflineTransportationType
                policyData={policyData}
              />
              <VehicleModificationData
                policyData={policyData}
                hidePhotos
              />
              <VehicleData
                policyData={policyData}
              />
              <VehiclePhotoData
                policyData={policyData}
              />
            </>
          )
        }
        <VehicleAttachmentData
          isManualOrder={pageConfig.isManualOrder}
          policyData={policyData}
        />
        <PolicyHolderInfo
          isManualOrder={pageConfig.isManualOrder}
          policyData={policyData}
        />
        {
          !isEmpty(quoteData?.instalment_details) && (
            <InstalmentsInfo
              instalmentsData={get(quoteData, 'instalment_details')}
              policy={policyData}
              isQuote
            />
          )
        }
        <PrintPolicyData policy={mapHardCopyData} />
        {
          !isHideInstantChecked && renderInstantApproval()
        }
        <BottomActionSheet
          show={showInstantTerms}
          onCloseSheet={handleShowTermsToggle}
        >
          <InstantTermsStyle>
            <Row justify='space-between' className='instant-terms-header'>
              <CustomText
                size='13px'
                weight='800'
                className='item-padding'
                color={AgentColorPallette.fontDarkerGrey}
              >
                {LANG_STRINGS.termsConditions}
              </CustomText>
              <CustomText
                size='15px'
                weight='800'
                className='item-padding'
                color={AgentColorPallette.fontDarkerGrey}
                onClick={handleShowTermsToggle}
              >
                X
              </CustomText>
            </Row>
            <CustomText
              size='1em'
              color={AgentColorPallette.blackGrey}
              className='bg-white'
              padLeft='12px'
              padRight='12px'
              padBottom='12px'
              top='12px'
            >
              {LANG_STRINGS.byCheckingThisYouAcceptTheOffers}
            </CustomText>
          </InstantTermsStyle>
        </BottomActionSheet>
      </OfflinePolicyDataStyle>
    </>
  )
}

export default OfflinePolicyContainer
