import { get } from 'lodash'
import { useMemo } from 'react'
import { CustomText } from '../../../../../components'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../PolicyInfoRender'

function PrintPolicyData ({ policy = {} }) {
  const printPolicyData = useMemo(() => {
    const insuranceDetails = get(policy, 'insurance_details', {})
    const hardCopyAddress = get(insuranceDetails, 'hard_copy_address', {})
    return [
      {
        title: LANG_STRINGS.province,
        value: get(hardCopyAddress, 'province_name', '-')
      },
      {
        title: LANG_STRINGS.city,
        value: get(hardCopyAddress, 'city_name', '-')
      },
      {
        title: LANG_STRINGS.postalCode,
        value: get(hardCopyAddress, 'postal_code', '-')
      },
      {
        title: LANG_STRINGS.shippingAddress,
        display: 'block',
        value: get(hardCopyAddress, 'address', '-')
      },
      ...(
        get(insuranceDetails, 'hard_copy_details.recipient_name', '-')
          ? [
            {
              title: LANG_STRINGS.policyReceiver,
              value: get(insuranceDetails, 'hard_copy_details.recipient_name', '-')
            },
            {
              title: LANG_STRINGS.activeMobileNumber,
              value: get(insuranceDetails, 'hard_copy_details.hard_copy_recipient_mobile', '-')
            }
          ] : []
      )
    ]
  }, [policy])

  return (
    <CollapsibleCard
      className={policy.hard_copy_required ? 'offline-collapsible-card-wrapper' : ''}
      title={LANG_STRINGS.printPolicy}
      isOpen
      key='printPolicyData'
    >
      {
        policy.hard_copy_required ? (
          <PolicyInfoRender data={printPolicyData} />
        ) : (
          <CustomText color={AgentColorPallette.darkCharcoal}>
            {LANG_STRINGS.thisOptionIsNotSelected}
          </CustomText>
        )
      }
    </CollapsibleCard>
  )
}

export default PrintPolicyData
