import { useMemo } from 'react'
import CollapsibleCard from '../../../../../components/CollapsibleCard'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../PolicyInfoRender'

function PolicyHolderInfo ({ policyData = {} }) {
  const policyHolderInfoData = useMemo(() => {
    return [
      {
        title: LANG_STRINGS.photoKTP,
        display: 'block',
        type: 'img',
        value: policyData?.ktp || policyData?.ktp_url
      },
      ...(
        (policyData?.npwp || policyData?.npwp_url) ? [{
          title: LANG_STRINGS.photoNPWP,
          display: 'block',
          type: 'img',
          value: policyData?.npwp || policyData?.npwp_url
        }] : []
      ),
      {
        title: LANG_STRINGS.ktpNumber,
        value: policyData?.ktp_no
      },
      {
        title: LANG_STRINGS.enterNameAsInKtp,
        value: policyData?.customer_name
      },
      {
        title: LANG_STRINGS.customerPhone,
        value: policyData.customer_phone_no || policyData?.mobile_no
      },
      {
        title: LANG_STRINGS.emailAddress,
        value: policyData.customer_email || policyData?.email
      },
      {
        title: LANG_STRINGS.province,
        value: policyData?.customer_address?.province_name
      },
      {
        title: LANG_STRINGS.city,
        value: policyData?.customer_address?.city_name
      },
      {
        title: LANG_STRINGS.postalCode,
        value: policyData?.customer_address?.postal_code
      },
      {
        title: LANG_STRINGS.addressAsKTP,
        display: 'block',
        value: policyData?.customer_address?.address
      }
    ]
  }, [policyData])

  return (
    <CollapsibleCard
      className='offline-collapsible-card-wrapper'
      title={LANG_STRINGS.policyHolderNew}
      isOpen
      key='PolicyHolderInfo'
    >
      <PolicyInfoRender
        data={policyHolderInfoData}
      />
    </CollapsibleCard>
  )
}

export default PolicyHolderInfo
