import moment from 'moment'
import 'moment/locale/id'
import PropTypes from 'prop-types'
import { useCallback, useMemo, useRef, useState } from 'react'
import { useHistory } from 'react-router'
import { Button, Modal } from '../../../../../components'
import PdfContainer from '../../../../../components/PdfContainer'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { formatMoney, getConvertedCurrency } from '../../../../../helpers/utility'
import { LANG_STRINGS } from '../../../../../lang'
import PolicyInfoRender from '../../../../CommonContainer/OfflinePolicyContainer/components/PolicyInfoRender'
import { InstalmentListItemStyle, InstalmentListStyle } from './index.style'
import { useParams } from 'react-router-dom'
moment.locale('id')

const InstalmentList = (props) => {
  const { instalments = [], currentInstalment = {}, policy } = props
  const fileUrl = useRef('')
  const [showFile, setShowFile] = useState(false)
  const history = useHistory()
  const { policyId } = useParams()

  const renderDocument = useCallback(
    () => {
      const onClose = () => {
        fileUrl.current = ''
        setShowFile(false)
      }
      const height = window.innerHeight - 40 > 600 ? 600 : window.innerHeight - 40
      return (
        <Modal
          isOpen={showFile}
          onClose={onClose}
        >
          <PdfContainer width='450' height={`${height}`} url={fileUrl.current} />
        </Modal>
      )
    }, [showFile])
  const sortedInstalments = useMemo(() => {
    const newInstalments = [...instalments]
    newInstalments.sort((a, b) => a.serial_number - b.serial_number)
    return newInstalments
  }, [instalments])

  const handleClickInvoice = (invoiceUrl) => {
    fileUrl.current = invoiceUrl
    setShowFile(true)
  }

  const handlePayInstalment = () => {
    history.push({
      pathname: `/payment/offline-online/${policyId}`
    })
  }

  const renderInstalments = sortedInstalments.map(instalment => {
    let rendered = []
    if (instalment.due_date) {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.instalmentDueDate,
          value: moment(instalment.due_date, 'YYYY/MM/DD').format('DD MMMM YYYY')
        }
      ]
    }
    if (instalment.payable_amount || instalment.payable_amount === 0) {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.totalBill,
          value: policy.currency_symbol !== 'Rp'
            ? formatMoney(getConvertedCurrency(instalment.payable_amount, policy.exchange_rate), 0, policy.currency_symbol, '.', ',')
            : formatMoney(instalment.payable_amount, '')
        }
      ]
    }
    if (instalment.payment_date && (instalment.transaction_status === 'PAID' || instalment.payment_proof_url)) {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.instalmentPaymentDate,
          value: moment(instalment.due_date, 'YYYY/MM/DD').format('DD/MM/YYYY')
        }
      ]
    }
    if (instalment.payment_by && instalment.transaction_status === 'PAID') {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.paidByNew,
          value: instalment.payment_by
        }
      ]
    }
    if (instalment.payment_method && instalment.transaction_status === 'PAID') {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.paymentMethod,
          value: instalment.payment_method
        }
      ]
    }
    const status = instalment.transaction_status === 'PAID'
      ? { value: LANG_STRINGS.alreadyPaid, color: AgentColorPallette.green }
      : instalment.payment_proof_url
        ? { value: LANG_STRINGS.paymentProofUploaded, color: AgentColorPallette.orange }
        : null
    if (status) {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.instalmentPaymentStatus,
          ...status
        }
      ]
    }
    if (instalment.invoice_url) {
      rendered = [
        ...rendered,
        {
          title: 'Invoice',
          value: (
            <Button
              id={`invoicebutton${instalment.serial_number}`}
              borderRadius='1rem'
              handleClick={() => handleClickInvoice(instalment.invoice_url)}
              width='fit-content'
              fontSize='8px'
              padTop='6px'
              padBtm='6px'
              padRt='12px'
              padLt='12px'
            >
              {LANG_STRINGS.lookInvoice}
            </Button>
          )
        }
      ]
    }
    if (instalment.serial_number === currentInstalment.serial_number) {
      rendered = [
        ...rendered,
        {
          title: LANG_STRINGS.payInstalment,
          value: (
            <Button
              id={`paymentbutton${instalment.serial_number}`}
              borderRadius='1rem'
              handleClick={handlePayInstalment}
              width='fit-content'
              fontSize='8px'
              padTop='6px'
              padBtm='6px'
              padRt='12px'
              padLt='12px'
            >
              {LANG_STRINGS.payInstalment}
            </Button>
          )
        }
      ]
    }
    return (
      <InstalmentListItemStyle
        bgColor={instalment.serial_number === currentInstalment.serial_number && AgentColorPallette.Gray90}
        key={`instalment-${instalment.serial_number}`}
      >
        <PolicyInfoRender data={rendered} name={`instalment-${instalment.serial_number}`} isBorder={false} isPadding />
      </InstalmentListItemStyle>
    )
  })
  return (
    <InstalmentListStyle>
      {renderInstalments}
      {renderDocument()}
    </InstalmentListStyle>
  )
}

InstalmentList.propTypes = {
  instalments: PropTypes.array,
  currentInstalment: PropTypes.object
}

export default InstalmentList
